import { Module, API } from '../index';

export interface Version {
  version: string;
  info?: { plain: string };
  [key: string]: any;
}

export interface UnknownEntries {
  [key: string]: {
    [key: string]: any;
  };
}

export interface Versions {
  latest?: Version;
  next?: Version;
  current?: Version;
}

export interface SubState {
  versions: Versions & UnknownEntries;
  dismissedVersionNotification: undefined | string;
}

export interface SubAPI {
  getCurrentVersion: () => Version;
  getLatestVersion: () => Version;
  versionUpdateAvailable: () => boolean;
}

// The `VERSIONCHECK` global is a JSON string injected into the bundle at build
// time by the manager webpack config. It contains the version data that was
// previously fetched at runtime over HTTP.
const getVersionCheckData = (): Versions => {
  try {
    return { ...(JSON.parse(VERSIONCHECK).data || {}) };
  } catch (e) {
    return {};
  }
};

export default function({ store, mode }: Module) {
  const { versions: persistedVersions } = store.getState();

  const { latest, next } = getVersionCheckData();

  const state = {
    versions: {
      ...persistedVersions,
      current: {
        version: currentVersion,
      },
      latest,
      next,
    },
  };

  const api: SubAPI = {
    getCurrentVersion: () => {
      const {
        versions: { current },
      } = store.getState();
      return current;
    },
    getLatestVersion: () => {
      const {
        versions: { latest: latestVersion },
      } = store.getState();
      return latestVersion;
    },
    versionUpdateAvailable: () => {
      const latestVersion = api.getLatestVersion();
      const current = api.getCurrentVersion();

      if (!latestVersion) {
        return false;
      }

      if (!latestVersion.version) {
        return true;
      }

      // A prerelease latest is never treated as an available update.
      if (semver.prerelease(latestVersion.version)) {
        return false;
      }

      // Strip any prerelease suffix off the current version so that e.g.
      // `3.1.0-alpha.0` is compared as `3.1.0` against the latest stable release.
      const currentStable = `${semver.major(current.version)}.${semver.minor(
        current.version
      )}.${semver.patch(current.version)}`;

      // Only minor & major increments count as an available update; patch
      // increments (and identical versions) do not.
      const diff = semver.diff(currentStable, latestVersion.version);

      return semver.gt(latestVersion.version, currentStable) && diff !== 'patch';
    },
  };

  const init = async ({ api: fullApi }: API) => {
    const { dismissedVersionNotification } = store.getState();

    const latestVersion = api.getLatestVersion();

    if (
      latestVersion &&
      latestVersion.version !== dismissedVersionNotification &&
      api.versionUpdateAvailable() &&
      mode !== 'production'
    ) {
      fullApi.addNotification({
        id: 'update',
        link: '/settings/about',
        content: `🎉 Storybook ${latestVersion.version} is available!`,
        onClear() {
          store.setState(
            { dismissedVersionNotification: latestVersion.version },
            { persistence: 'permanent' }
          );
        },
      });
    }
  };

  return { init, state, api };
}
