+import initVersions from '../modules/versions';
+
+jest.mock('../version', () => ({ version: '3.0.0' }));
+jest.mock('global', () => ({
+  VERSIONCHECK: JSON.stringify({ data: { latest: { version: '4.0.0' }, next: { version: '4.1.0-alpha.0' } } }),
+}));
+
+function createMockStore() {
+  let state = {};
+  return {
+    getState: jest.fn(() => state),
+    setState: jest.fn(s => { state = { ...state, ...s }; return Promise.resolve(state); }),
+  };
+}
+
+describe('build-time versions', () => {
+  it('initial state populated from VERSIONCHECK', () => {
+    const store = createMockStore();
+    const { state } = initVersions({ store });
+    expect(state.versions.current).toEqual({ version: '3.0.0' });
+    expect(state.versions.latest).toEqual({ version: '4.0.0' });
+    expect(state.versions.next).toEqual({ version: '4.1.0-alpha.0' });
+  });
+  it('api getters + update available', () => {
+    const store = createMockStore();
+    const { state, api } = initVersions({ store });
+    store.setState(state);
+    expect(api.getCurrentVersion()).toEqual({ version: '3.0.0' });
+    expect(api.getLatestVersion()).toEqual({ version: '4.0.0' });
+    expect(api.versionUpdateAvailable()).toBe(true);
+  });
+  it('adds notification (non-prod) and persists dismissal', async () => {
+    const store = createMockStore();
+    const { state, api, init } = initVersions({ store });
+    store.setState(state);
+    let n;
+    await init({ api: { addNotification: jest.fn(x => { n = x; }), ...api } });
+    expect(n).toBeDefined();
+    n.onClear();
+    expect(store.setState).toHaveBeenCalledWith({ dismissedVersionNotification: '4.0.0' }, { persistence: 'permanent' });
+  });
+  it('no notification in production', async () => {
+    const store = createMockStore();
+    const { state, api, init } = initVersions({ store, mode: 'production' });
+    store.setState(state);
+    const addNotification = jest.fn();
+    await init({ api: { addNotification, ...api } });
+    expect(addNotification).not.toHaveBeenCalled();
+  });
+});
